INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 10, 'theory', 'Quiz: multi-file projects');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 0, 'How does a declaration differ from a definition?', '["A declaration may appear only in a .c file, a definition only in a .h file", "A definition may be repeated any number of times, a declaration only once", "A declaration gives a name and a type, a definition creates the entity (memory or code); there must be exactly one definition per program", "There is no difference: they are synonyms"]', 2, 'extern int x; and a function prototype are declarations, and there may be many. int x = 0; and a function body are definitions: two definitions give "multiple definition", none gives "undefined reference".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 1, 'What does the word static do in front of a global function or variable in a .c file?', '["Makes it accessible from all files", "Gives it internal linkage: the name is visible only in this file and does not clash with same-named ones in other files", "Places it on the stack", "Forbids modifying it"]', 1, 'This is the simplest encapsulation in C: everything that is not part of the module''s interface is marked static. Inside a function, static means something else: the variable lives between calls.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 2, 'Why are static libraries written on the command line after the object files that refer to them?', '["The preprocessor requires it", "Otherwise the library would not be copied to disk", "The order does not matter", "The linker scans the archive once, left to right, and takes only the objects needed for symbols that are already undefined"]', 3, 'If the library comes first, there are no undefined symbols yet, so none of its objects is extracted. For libraries with circular dependencies, use a group (--start-group).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 3, 'By what criterion does make decide to rebuild a target?', '["The target is missing or older than any of its dependencies by modification time", "By the size of the target file", "By the name of the target", "By the number of lines in the sources"]', 0, 'make builds a dependency graph and compares modification times: only what depends on the changed files is rebuilt. For this to work, the dependencies must be written correctly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 10, 4, 'What problem do the compiler flags -MMD -MP together with -include in a Makefile solve?', '["Speed up compilation several times over", "Enable warnings", "Automatically record header dependencies, so that editing a .h rebuilds the .c files that use it", "Make the linker search for libraries"]', 2, 'make knows only the dependencies that are written down. The .d files created by the compiler contain the real #include lines, so the graph is always up to date.');
